package hikyubank.dataaccess.postgresql;
import java.util.*;import java.math.BigDecimal;import java.time.*;import java.sql.*;
import org.springframework.stereotype.Repository;import org.springframework.jdbc.core.JdbcTemplate;
import hikyubank.application.dto.BankingDtos.*;
@Repository public class BankingRepository {
 private final JdbcTemplate jdbc;public BankingRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<Map<String,Object>> lockAccounts(UUID user,UUID source,UUID target){return jdbc.queryForList("SELECT * FROM hikyu.accounts WHERE user_id=? AND id IN (?,?) ORDER BY id FOR UPDATE",user,source,target==null?source:target);}
 private Payee payee(ResultSet r)throws SQLException{return new Payee(r.getObject("id",UUID.class),r.getString("kind"),r.getString("identifier"),r.getString("alias"),r.getString("reference"));}
 public List<Payee> payees(UUID user){return jdbc.query("SELECT * FROM hikyu.saved_payees WHERE user_id=? AND NOT deleted ORDER BY kind,alias,id",(r,n)->payee(r),user);}
 public Payee payee(UUID user,UUID id){return jdbc.query("SELECT * FROM hikyu.saved_payees WHERE user_id=? AND id=? AND NOT deleted",(r,n)->payee(r),user,id).stream().findFirst().orElse(null);}
 public UUID savePayee(UUID user,PayeeInput p){return jdbc.queryForObject("INSERT INTO hikyu.saved_payees(id,user_id,kind,identifier,alias,reference) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id,kind,identifier) DO UPDATE SET alias=EXCLUDED.alias,reference=EXCLUDED.reference,deleted=FALSE RETURNING id",UUID.class,UUID.randomUUID(),user,p.kind(),p.identifier(),p.alias().trim(),p.reference()==null?"":p.reference().trim());}
 public int editPayee(UUID user,UUID id,PayeeEdit p){return jdbc.update("UPDATE hikyu.saved_payees SET alias=?,reference=? WHERE user_id=? AND id=? AND NOT deleted",p.alias().trim(),p.reference()==null?"":p.reference().trim(),user,id);}
 public int deletePayee(UUID user,UUID id){return jdbc.update("UPDATE hikyu.saved_payees SET deleted=TRUE WHERE user_id=? AND id=? AND NOT deleted",user,id);}
 public void ensureCards(UUID user){jdbc.update("INSERT INTO hikyu.card_controls(account_id) SELECT id FROM hikyu.accounts WHERE user_id=? AND type IN('checking','credit') ON CONFLICT DO NOTHING",user);}
 public List<Card> cards(UUID user){ensureCards(user);return jdbc.query("SELECT a.*,c.locked FROM hikyu.accounts a JOIN hikyu.card_controls c ON c.account_id=a.id WHERE a.user_id=? ORDER BY a.type,a.id",(r,n)->new Card(r.getObject("id",UUID.class),r.getString("name"),r.getString("type"),r.getString("suffix"),r.getString("status"),r.getBigDecimal("balance"),r.getBoolean("locked")),user);}
 public boolean locked(UUID user,UUID account){ensureCards(user);return jdbc.queryForObject("SELECT c.locked FROM hikyu.card_controls c JOIN hikyu.accounts a ON a.id=c.account_id WHERE c.account_id=? AND a.user_id=? FOR UPDATE OF c",Boolean.class,account,user);}
 public int lockCard(UUID user,UUID account,boolean locked){return jdbc.update("UPDATE hikyu.card_controls c SET locked=? FROM hikyu.accounts a WHERE a.id=c.account_id AND a.user_id=? AND a.id=? AND a.status='active'",locked,user,account);}
 private OperationReceipt receipt(ResultSet r)throws SQLException{return new OperationReceipt(r.getObject("id",UUID.class),r.getString("kind"),r.getObject("source_account_id",UUID.class),r.getObject("target_account_id",UUID.class),r.getBigDecimal("amount"),r.getString("merchant"),r.getString("category"),r.getString("note"),r.getTimestamp("created_at").toInstant(),"completed");}
 public List<OperationReceipt> history(UUID user){return jdbc.query("SELECT * FROM hikyu.financial_operations WHERE user_id=? ORDER BY created_at DESC,id LIMIT 100",(r,n)->receipt(r),user);}
 public OperationReceipt existing(UUID user,UUID key){return jdbc.query("SELECT * FROM hikyu.financial_operations WHERE user_id=? AND idempotency_key=?",(r,n)->receipt(r),user,key).stream().findFirst().orElse(null);}
 public String requestHash(UUID user,UUID key){return jdbc.queryForObject("SELECT request_hash FROM hikyu.financial_operations WHERE user_id=? AND idempotency_key=?",String.class,user,key);}
 public void operation(UUID id,UUID user,OperationInput p,String merchant,String category,String hash,Instant now){jdbc.update("INSERT INTO hikyu.financial_operations(id,user_id,kind,source_account_id,target_account_id,payee_id,amount,merchant,category,note,idempotency_key,request_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",id,user,p.type(),p.sourceAccountId(),p.targetAccountId(),p.payeeId(),p.amount(),merchant,category,p.note()==null?"":p.note().trim(),p.idempotencyKey(),hash,Timestamp.from(now));}
 public void leg(UUID operation,UUID account,String merchant,String category,BigDecimal amount,String kind,String note,Instant now){jdbc.update("INSERT INTO hikyu.transactions(id,account_id,name,category,posted_date,amount,icon,kind,note,operation_id) VALUES(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),account,merchant,category,java.sql.Date.valueOf(LocalDate.ofInstant(now,ZoneOffset.UTC)),amount,"◈",kind,note==null?"":note.trim(),operation);}
 public void reduceCredit(UUID id,BigDecimal amount){jdbc.update("UPDATE hikyu.accounts SET balance=balance-?,minimum_due=LEAST(GREATEST(COALESCE(minimum_due,0)-?,0),balance-?) WHERE id=?",amount,amount,amount,id);}
 public boolean claim(UUID operation,UUID alert){return jdbc.update("INSERT INTO hikyu.financial_alert_events(operation_id,alert_id) VALUES(?,?) ON CONFLICT DO NOTHING",operation,alert)==1;}
 public UUID saveBudget(UUID user,UUID id,LocalDate month,BudgetInput p){if(id==null)return jdbc.queryForObject("INSERT INTO hikyu.budgets(id,user_id,month,category,limit_amount) VALUES(?,?,?,?,?) ON CONFLICT(user_id,month,category) DO UPDATE SET limit_amount=EXCLUDED.limit_amount RETURNING id",UUID.class,UUID.randomUUID(),user,java.sql.Date.valueOf(month),p.category(),p.limit());return jdbc.update("UPDATE hikyu.budgets SET month=?,category=?,limit_amount=? WHERE id=? AND user_id=?",java.sql.Date.valueOf(month),p.category(),p.limit(),id,user)==1?id:null;}
 public int deleteBudget(UUID user,UUID id){return jdbc.update("DELETE FROM hikyu.budgets WHERE user_id=? AND id=?",user,id);}
 public List<Budget> budgets(UUID user,LocalDate month){return jdbc.query("""
  SELECT b.*,COALESCE((SELECT SUM(-t.amount) FROM hikyu.transactions t JOIN hikyu.accounts a ON a.id=t.account_id
   WHERE a.user_id=b.user_id AND t.category=b.category AND t.amount<0 AND t.kind IN('expense','peer_transfer')
   AND t.posted_date>=b.month AND t.posted_date<b.month+INTERVAL '1 month'),0) AS spent
  FROM hikyu.budgets b WHERE b.user_id=? AND b.month=? ORDER BY b.category,b.id
  """,(r,n)->{var limit=r.getBigDecimal("limit_amount");var spent=r.getBigDecimal("spent");return new Budget(r.getObject("id",UUID.class),month.toString().substring(0,7),r.getString("category"),limit,spent,limit.subtract(spent),spent.compareTo(limit)>0);},user,java.sql.Date.valueOf(month));}
 public List<Map<String,Object>> statement(UUID user,UUID account,LocalDate from,LocalDate to){return jdbc.queryForList("SELECT t.*,a.name AS account_name FROM hikyu.transactions t JOIN hikyu.accounts a ON a.id=t.account_id WHERE a.user_id=? AND (?::uuid IS NULL OR a.id=?::uuid) AND t.posted_date>=? AND t.posted_date<=? ORDER BY t.posted_date,t.id LIMIT 10001",user,account,account,java.sql.Date.valueOf(from),java.sql.Date.valueOf(to));}
}
